script:
frappe.ui.form.on('Student Applicant', {
    refresh: function (frm) {

        frm.set_query('academic_term', function () {
            return {
                filters: {
                    academic_year: frm.doc.academic_year
                }
            };
        });

        if (!frm.is_new() && frm.doc.application_status === 'Approved') {
            frm.add_custom_button(__('Enroll'), function () {
                frm.events.enroll(frm);
            });
        }
    },

    enroll: function (frm) {

        frappe.route_options = {
            student_applicant: frm.doc.name,
            first_name: frm.doc.first_name,
            last_name: frm.doc.last_name,
            student_email_id: frm.doc.student_email_id,
            student_mobile_number: frm.doc.student_mobile_number,
            date_of_birth: frm.doc.date_of_birth,
            gender: frm.doc.gender,
            academic_year: frm.doc.academic_year,
            program: frm.doc.program,
            grade_joined: frm.doc.program,

            // Address fields
            address_line_1: frm.doc.address_line_1,
            pincode: frm.doc.pincode
        };

        frappe.new_doc('Student');
    }
});
